#include <iostream>
#include <map>
#include <vector>
using namespace std;

const int MOD = 1000000007;

struct BigNumber {
    int number;

    BigNumber(long long v = 0) {
        if (v < 0) v %= MOD, v += MOD;
        if (v >= MOD) v %= MOD;
        number = v;
    }

    static int modInverse(int a, int m = MOD) {
        int g = m, r = a, x = 0, y = 1;
        while (r != 0) {
            int q = g / r;
            g %= r; swap(g, r);
            x -= q * y; swap(x, y);
        }
        return x < 0 ? x + m : x;
    }

    explicit operator int() const { return number; }

    BigNumber& operator+=(const BigNumber &other) {
        number += other.number;
        if (number >= MOD) number -= MOD;
        return *this;
    }

    BigNumber& operator-=(const BigNumber &other) {
        number -= other.number;
        if (number < 0) number += MOD;
        return *this;
    }

    static unsigned fast_mod(uint64_t x, unsigned m = MOD) {
    #if !defined(_WIN32) || defined(_WIN64)
        return x % m;
    #endif
        unsigned high = x >> 32, low = (unsigned) x;
        unsigned q, r;
        asm("divl %4\n"
            : "=a" (q), "=d" (r)
            : "d" (high), "a" (low), "r" (m));
        return r;
    }

    BigNumber& operator*=(const BigNumber &other) {
        number = fast_mod((uint64_t) number * other.number);
        return *this;
    }

    BigNumber& operator/=(const BigNumber &other) {
        return *this *= BigNumber(modInverse(other.number));
    }

    friend BigNumber operator+(const BigNumber &a, const BigNumber &b) { return BigNumber(a) += b; }
    friend BigNumber operator-(const BigNumber &a, const BigNumber &b) { return BigNumber(a) -= b; }
    friend BigNumber operator*(const BigNumber &a, const BigNumber &b) { return BigNumber(a) *= b; }
    friend BigNumber operator/(const BigNumber &a, const BigNumber &b) { return BigNumber(a) /= b; }

    BigNumber& operator++() {
        number = number == MOD - 1 ? 0 : number + 1;
        return *this;
    }

    BigNumber& operator--() {
        number = number == 0 ? MOD - 1 : number - 1;
        return *this;
    }

    BigNumber operator++(int) { BigNumber before = *this; ++*this; return before; }
    BigNumber operator--(int) { BigNumber before = *this; --*this; return before; }

    BigNumber operator-() const {
        return number == 0 ? 0 : MOD - number;
    }

    bool operator==(const BigNumber &other) const { return number == other.number; }
    bool operator!=(const BigNumber &other) const { return number != other.number; }

    BigNumber inv() const {
        return BigNumber(modInverse(number));
    }

    BigNumber pow(long long p) const {
        assert(p >= 0);
        BigNumber base = *this, result = 1;
        while (p > 0) {
            if (p & 1)
                result *= base;
            base *= base;
            p >>= 1;
        }
        return result;
    }
};

const int MAX_N = 7;

int N;
BigNumber prob[MAX_N][MAX_N];

int main() {
    cin >> N;
    for (int i = 0; i < N; i++)
        for (int j = 0; j < N; j++) {
            int p;
            cin >> p;
            prob[i][j] = BigNumber(p) / BigNumber(100);
        }

    map<vector<bool>, BigNumber> state_map;
    vector<bool> initial_mask(1 << N, false);
    initial_mask[0] = true;
    state_map[initial_mask] = 1;
    vector<bool> temp_mask;

    for (int left_idx = 0; left_idx < N; left_idx++) {
        map<vector<bool>, BigNumber> new_state_map;
        for (int mask_curr = 0; mask_curr < (1 << N); mask_curr++) {
            BigNumber product = 1;
            for (int right_idx = 0; right_idx < N; right_idx++)
                product *= (mask_curr >> right_idx & 1) ? prob[left_idx][right_idx] : BigNumber(1) - prob[left_idx][right_idx];

            for (auto &entry : state_map) {
                const vector<bool> &possible_mask = entry.first;
                BigNumber prob_value = entry.second;
                temp_mask.assign(1 << N, false);
                for (int m = 0; m < (1 << N); m++)
                    if (possible_mask[m])
                        for (int i = 0; i < N; i++)
                            if ((mask_curr >> i & 1) != 0 && (m >> i & 1) == 0)
                                temp_mask[m | (1 << i)] = true;

                new_state_map[temp_mask] += prob_value * product;
            }
        }
        state_map = new_state_map;
    }

    BigNumber total = 0;
    for (auto &p : state_map)
        if (p.first[(1 << N) - 1])
            total += p.second;

    cout << (int) total << '\n';
}
